/**
 * Nihongo Pro Academy / Nihongo Pro Academy — Platform Core v21
 * Shared state, XP system, navigation, toasts, theme
 */
(function(global) {
  'use strict';

  // ═══════════════════════════════════════════════════════
  // STATE MANAGEMENT
  // ═══════════════════════════════════════════════════════
  const STATE_KEY = 'np-state-v3';
  const SRS_KEY   = 'np-srs-v2';

  /* Status premium TEPERCAYA.

     JANGAN percaya u.isPremium dari localStorage — pengguna bisa mengubahnya
     lewat DevTools dan mendapat premium gratis. Kebenaran ada di Supabase
     session (user_metadata.is_premium), yang di-set server setelah webhook
     pembayaran terverifikasi.

     Aman-mundur: bila Supabase belum termuat atau belum login → false (bukan
     premium). Penegakan sebenarnya tetap server-side; ini untuk keputusan UX
     (kuota, gating tampilan). */
  function verifiedPremium() {
    try {
      var SB = global.SupabaseClient;
      var user = SB && SB.Auth && SB.Auth.user && SB.Auth.user();
      if (!user) return false;
      var meta = user.user_metadata || {};
      var appMeta = user.app_metadata || {};
      return !!(meta.is_premium || appMeta.is_premium);
    } catch (e) { return false; }
  }

  function loadState() {
    try { return JSON.parse(localStorage.getItem(STATE_KEY) || '{}'); } catch { return {}; }
  }
  function saveState(s) {
    localStorage.setItem(STATE_KEY, JSON.stringify(s));
  }

  const DEFAULT_USER = {
    name: '', email: '', avatar: '', isPremium: false,
    xp: 0, level: 1, streak: 0, lastStudyDate: null,
    studyDates: [], studyMinutesToday: 0, lastStudyReset: null,
    dailyGoalMin: 20, weeklyGoalDays: 5,
    jlptProgress: { N5: 0, N4: 0, N3: 0, N2: 0, N1: 0 },
    kaigoProgress: 0, kaigoModules: {},
    kanjiLearned: 0, grammarLearned: 0, vocabLearned: 0,
    quizTotal: 0, quizCorrect: 0, liveClassCount: 0,
    achievements: [], badges: [],
    aiMsgsToday: 0, aiMsgDate: null,
  };

  let _state = loadState();
  if (!_state.user) _state.user = { ...DEFAULT_USER };

  // Merge missing keys
  Object.keys(DEFAULT_USER).forEach(k => {
    if (_state.user[k] === undefined) _state.user[k] = DEFAULT_USER[k];
  });

  if (typeof window !== 'undefined') {
    window.addEventListener('storage', (e) => {
      if (e.key === STATE_KEY && e.newValue) {
        try { _state = JSON.parse(e.newValue); } catch (err) { /* genuinely abaikan JSON korup, pertahankan state saat ini */ }
      }
    });
  }

  const State = {
    get: ()    => _state,
    getUser: () => _state.user,
    save: ()   => saveState(_state),

    updateUser(patch) {
      Object.assign(_state.user, patch);
      saveState(_state);
      global.dispatchEvent(new CustomEvent('np:userUpdated', { detail: _state.user }));
    },

    // XP + Level
    addXP(amount, reason) {
      const u = _state.user;
      const oldLevel = u.level;
      u.xp += amount;
      u.level = XP.levelFromXP(u.xp);
      saveState(_state);
      Toast.show(`+${amount} XP ${reason ? '— ' + reason : ''}`, 'gold');
      if (u.level > oldLevel) {
        setTimeout(() => Toast.show(`🎉 Level Up! Sekarang Level ${u.level}`, 'success'), 600);
      }
      global.dispatchEvent(new CustomEvent('np:xpAdded', { detail: { amount, reason, total: u.xp, level: u.level } }));
      return u.xp;
    },

    // Study timer
    markStudyToday() {
      const u = _state.user;
      const today = new Date().toDateString();
      if (u.lastStudyReset !== today) {
        u.studyMinutesToday = 0;
        u.lastStudyReset = today;
        u.aiMsgsToday = 0;
        u.aiMsgDate = today;
      }
      if (!u.studyDates.includes(today)) {
        u.studyDates.push(today);
        u.studyDates = u.studyDates.slice(-365);
        // Update streak
        const yesterday = new Date();
        yesterday.setDate(yesterday.getDate() - 1);
        const yds = yesterday.toDateString();
        if (u.lastStudyDate === yds || u.lastStudyDate === today) {
          if (u.lastStudyDate !== today) u.streak += 1;
        } else {
          u.streak = 1;
        }
        u.lastStudyDate = today;
        saveState(_state);
        global.dispatchEvent(new CustomEvent('np:streakUpdated', { detail: u.streak }));
      }
    },

    addStudyMinutes(mins) {
      const u = _state.user;
      const today = new Date().toDateString();
      if (u.lastStudyReset !== today) { u.studyMinutesToday = 0; u.lastStudyReset = today; }
      u.studyMinutesToday += mins;
      saveState(_state);
    },

    // AI rate limit
    canUseAI() {
      const u = _state.user;
      if (verifiedPremium()) return true;
      const today = new Date().toDateString();
      if (u.aiMsgDate !== today) { u.aiMsgsToday = 0; u.aiMsgDate = today; saveState(_state); }
      return u.aiMsgsToday < 10;
    },
    useAIMsg() {
      const u = _state.user;
      const today = new Date().toDateString();
      if (u.aiMsgDate !== today) { u.aiMsgsToday = 0; u.aiMsgDate = today; }
      u.aiMsgsToday++;
      saveState(_state);
      return u.aiMsgsToday;
    },
    getAIRemaining() {
      const u = _state.user;
      if (verifiedPremium()) return Infinity;
      const today = new Date().toDateString();
      if (u.aiMsgDate !== today) return 10;
      return Math.max(0, 10 - (u.aiMsgsToday || 0));
    },
  };

  // ═══════════════════════════════════════════════════════
  // XP SYSTEM
  // ═══════════════════════════════════════════════════════
  const XP_LEVELS = [0,100,250,500,900,1500,2500,4000,6000,9000,13000,18000,25000,34000,45000];
  const XP = {
    levelFromXP(xp) {
      let lv = 1;
      for (let i = 1; i < XP_LEVELS.length; i++) { if (xp >= XP_LEVELS[i]) lv = i + 1; }
      return lv;
    },
    levelProgress(xp) {
      const lv = this.levelFromXP(xp);
      const cur = XP_LEVELS[Math.min(lv - 1, XP_LEVELS.length - 1)];
      const nxt = XP_LEVELS[Math.min(lv, XP_LEVELS.length - 1)];
      const pct = nxt > cur ? Math.round((xp - cur) / (nxt - cur) * 100) : 100;
      return Math.max(0, Math.min(100, pct)); // clamp: defends against negative/odd xp values
    },
    nextLevel(xp) {
      const lv = this.levelFromXP(xp);
      return XP_LEVELS[Math.min(lv, XP_LEVELS.length - 1)];
    },
    levelTitle(lv) {
      const titles = ['','見習い','初心者','学習者','上達中','中級者','上級者','熟練者','達人','エキスパート','マスター','上師','賢者','博士','伝説','創始者'];
      return titles[Math.min(lv, titles.length - 1)] || 'マスター';
    },
  };

  // ═══════════════════════════════════════════════════════
  // SRS FLASHCARD ALGORITHM (SM-2)
  // ═══════════════════════════════════════════════════════
  const SRS = {
    loadCards() { try { return JSON.parse(localStorage.getItem(SRS_KEY) || '{}'); } catch { return {}; } },
    saveCards(c) { localStorage.setItem(SRS_KEY, JSON.stringify(c)); },
    defaultCard(id) { return { id, ef: 2.5, interval: 0, reps: 0, nextReview: Date.now(), lastRating: null }; },

    // rating: 0=Again 1=Hard 2=Good 3=Easy
    rate(cardId, rating) {
      // Defensive validation: invalid rating used to silently fall through
      // to the "Easy" branch (longest interval) — now it's a no-op + console warning.
      // Note: check raw type first — Number(null)===0 and Number('')===0 would
      // otherwise be wrongly accepted as a valid "Again" rating.
      const isValidRaw = typeof rating === 'number' || (typeof rating === 'string' && rating.trim() !== '');
      const numRating = isValidRaw ? Number(rating) : NaN;
      if (!Number.isInteger(numRating) || numRating < 0 || numRating > 3) {
        console.warn('[SRS] Invalid rating "' + rating + '" for card "' + cardId + '" — ignored. Expected 0-3.');
        const cards = this.loadCards();
        return cards[cardId] || this.defaultCard(cardId);
      }
      rating = numRating;
      const cards = this.loadCards();
      const c = cards[cardId] || this.defaultCard(cardId);
      let ef = Math.max(1.3, c.ef);
      let interval;
      if (rating === 0) {
        interval = 1; ef = Math.max(1.3, ef - 0.2); c.reps = 0;
      } else if (rating === 1) {
        interval = c.reps === 0 ? 6 : Math.round(c.interval * 1.2);
        ef = Math.max(1.3, ef - 0.15);
      } else if (rating === 2) {
        interval = c.reps === 0 ? 10 : c.reps === 1 ? 1440 : Math.round(c.interval * ef);
      } else {
        interval = c.reps === 0 ? 5760 : Math.round(c.interval * ef * 1.3);
        ef = Math.min(3, ef + 0.1);
      }
      c.interval = Math.max(1, interval);
      c.ef = ef;
      c.reps = rating === 0 ? 0 : c.reps + 1;
      c.nextReview = Date.now() + c.interval * 60 * 1000;
      c.lastRating = rating;
      c.lastReviewed = Date.now();
      cards[cardId] = c;
      this.saveCards(cards);
      return c;
    },

    isDue(cardId) {
      const cards = this.loadCards();
      const c = cards[cardId];
      return !c || c.nextReview <= Date.now();
    },

    intervalText(cardId, rating) {
      const cards = this.loadCards();
      const c = cards[cardId] || this.defaultCard(cardId);
      const mins = rating === 0 ? 1 : rating === 1 ? Math.max(6, Math.round(c.interval * 1.2)) :
                   rating === 2 ? (c.reps === 0 ? 10 : 1440) : 5760;
      if (mins < 60) return mins + 'm';
      if (mins < 1440) return Math.round(mins / 60) + 'h';
      return Math.round(mins / 1440) + 'd';
    },

    getStats(allIds) {
      const cards = this.loadCards();
      const now = Date.now();
      return {
        due:     allIds.filter(id => !cards[id] || cards[id].nextReview <= now).length,
        new:     allIds.filter(id => !cards[id] || cards[id].reps === 0).length,
        learned: allIds.filter(id => cards[id] && cards[id].reps > 0).length,
        retention: (() => {
          const rated = allIds.filter(id => cards[id] && cards[id].lastRating !== null);
          if (!rated.length) return 0;
          const good = rated.filter(id => cards[id].lastRating >= 2).length;
          return Math.round(good / rated.length * 100);
        })(),
      };
    },
  };

  // ═══════════════════════════════════════════════════════
  // AI ABSTRACTION LAYER
  // ═══════════════════════════════════════════════════════
  const AI = {
    endpoint: (window.EDUMA_ENV?.AI_API_ENDPOINT) || '/api/ai-chat',

    async chat(messages, options = {}) {
      if (!State.canUseAI()) {
        throw new Error('LIMIT_REACHED');
      }
      const res = await fetch(this.endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          messages,
          model: options.model || 'gpt-4o-mini',
          max_tokens: options.maxTokens || 500,
          temperature: options.temperature || 0.4,
        }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.error || 'AI request failed');
      }
      const data = await res.json();
      State.useAIMsg();
      return data.text || data.choices?.[0]?.message?.content || '';
    },

    buildSystemPrompt(mode, level, scenario, user) {
      const modeInstructions = {
        grammar:      `Koreksi grammar Jepang user. Tunjukkan kesalahan, perbaikan, dan penjelasan aturan. Format: ❌ Salah → ✅ Benar → 📖 Penjelasan.`,
        conversation: `Percakapan Jepang sesuai level ${level}. Skenario: ${scenario}. Natural, helpful, koreksi jika salah.`,
        jlpt:         `JLPT Coach level ${level}. Skenario: ${scenario}. Beri soal, penjelasan, tips mengingat.`,
        kaigo:        `Kaigo language specialist. Skenario: ${scenario}. Bahasa kaigo nyata, situasi 介護現場.`,
        interview:    `Pewawancara kerja Jepang. Skenario: ${scenario}. Evaluasi jawaban, saran perbaikan.`,
        writing:      `Review tulisan Jepang. Koreksi grammar, naturalness, kesan keseluruhan.`,
        kaiwa:        `Roleplay simulator. Skenario: ${scenario}. Mainkan karakter, berikan feedback di akhir.`,
      };
      return `Kamu adalah Tanaka Sensei, AI Tutor bahasa Jepang dan kaigo terbaik dari platform Nihongo Pro Academy.
Profil pelajar: Nama=${user?.name||'Pelajar'}, Level=${level}, XP=${user?.xp||0}, Streak=${user?.streak||0}hari.
Mode: ${modeInstructions[mode] || modeInstructions.conversation}
Format: Bahasa Indonesia + Japanese. Romaji untuk kata sulit. Max 3-4 kalimat, padat dan jelas.
Jika ada kesalahan grammar, tandai [KOREKSI: ...]. Vocab baru: [VOCAB: 語=arti].
Akhiri dengan pertanyaan atau prompt untuk lanjut belajar.`;
    },
  };

  // ═══════════════════════════════════════════════════════
  // TOAST
  // ═══════════════════════════════════════════════════════
  const Toast = {
    container: null,
    init() {
      if (this.container) return;
      this.container = document.createElement('div');
      this.container.className = 'toast-container';
      document.body.appendChild(this.container);
    },
    show(msg, type = '', duration = 3000) {
      this.init();
      const el = document.createElement('div');
      el.className = `toast ${type}`;
      el.innerHTML = `<span>${msg}</span>`;
      el.onclick = () => el.remove();
      this.container.appendChild(el);
      requestAnimationFrame(() => requestAnimationFrame(() => el.classList.add('show')));
      setTimeout(() => { el.classList.remove('show'); setTimeout(() => el.remove(), 400); }, duration);
    },
  };

  // ═══════════════════════════════════════════════════════
  // THEME
  // ═══════════════════════════════════════════════════════
  const Theme = {
    init() {
      // Jika window.NPDark sudah ada (dark-mode-toggle.js dimuat lebih dulu
      // di halaman ini), sistem itu adalah sumber kebenaran tunggal — jangan
      // menimpa data-theme dengan key localStorage berbeda ('np-theme').
      if (typeof window.NPDark === 'object' && window.NPDark !== null) {
        this.updateButtons();
        return;
      }
      const t = localStorage.getItem('np-theme') || 'light';
      document.documentElement.setAttribute('data-theme', t === 'dark' ? 'dark' : '');
      this.updateButtons();
    },
    toggle() {
      if (typeof window.NPDark === 'object' && window.NPDark !== null) {
        window.NPDark.toggle();
        this.updateButtons();
        return;
      }
      const dark = document.documentElement.getAttribute('data-theme') === 'dark';
      document.documentElement.setAttribute('data-theme', dark ? '' : 'dark');
      localStorage.setItem('np-theme', dark ? 'light' : 'dark');
      this.updateButtons();
    },
    updateButtons() {
      const dark = document.documentElement.getAttribute('data-theme') === 'dark';
      document.querySelectorAll('[data-theme-toggle]').forEach(b => {
        b.textContent = dark ? '☀️' : '🌙';
        b.setAttribute('aria-label', dark ? 'Mode terang' : 'Mode gelap');
      });
    },
  };

  // ═══════════════════════════════════════════════════════
  // NAVIGATION — build mobile bottom nav
  // ═══════════════════════════════════════════════════════
  const Nav = {
    ITEMS: [
      { icon: '🏠', label: 'Beranda',   url: 'index.html',              match: ['index'] },
      { icon: '📚', label: 'Materi',    url: 'Materi/Materi.html',      match: ['Materi'] },
      { icon: '🎯', label: 'CBT',       url: 'JLPT-CBT.html',           match: ['JLPT-CBT'] },
      { icon: '🃏', label: 'SRS',       url: 'SRS-Flashcard.html',      match: ['SRS-Flashcard'] },
      { icon: '📊', label: 'Dashboard', url: 'Dashboard/Dashboard.html',match: ['Dashboard'] },
    ],
    init(prefix = '') {
      const nav = document.createElement('nav');
      nav.className = 'mobile-nav';
      nav.setAttribute('aria-label', 'Navigasi utama');
      const path = location.pathname;
      nav.innerHTML = this.ITEMS.map(item => {
        const active = item.match.some(m => path.includes(m));
        return `<a href="${prefix}${item.url}" class="mobile-nav-item${active ? ' active' : ''}" aria-label="${item.label}">
          <span class="icon">${item.icon}</span>${item.label}</a>`;
      }).join('');
      document.body.appendChild(nav);
    },
  };

  // ═══════════════════════════════════════════════════════
  // ACHIEVEMENT CHECKER
  // ═══════════════════════════════════════════════════════
  const Achievements = {
    ALL: [
      { id: 'first_login',   icon: '🌱', title: 'Langkah Pertama',    xp: 10,  check: u => true },
      { id: 'streak_3',      icon: '🔥', title: '3 Hari Berturut',    xp: 30,  check: u => u.streak >= 3 },
      { id: 'streak_7',      icon: '🔥', title: 'Seminggu Penuh',     xp: 100, check: u => u.streak >= 7 },
      { id: 'streak_30',     icon: '⚡', title: 'Sebulan Konsisten',  xp: 500, check: u => u.streak >= 30 },
      { id: 'xp_500',        icon: '⭐', title: 'XP 500',            xp: 0,   check: u => u.xp >= 500 },
      { id: 'xp_5000',       icon: '🌟', title: 'XP 5000',           xp: 0,   check: u => u.xp >= 5000 },
      { id: 'quiz_10',       icon: '🎯', title: 'Quiz Pemula',        xp: 50,  check: u => u.quizTotal >= 10 },
      { id: 'quiz_100',      icon: '🏆', title: 'Quiz Champion',      xp: 200, check: u => u.quizTotal >= 100 },
      { id: 'kanji_50',      icon: '🈶', title: 'Kanji Enthusiast',   xp: 80,  check: u => u.kanjiLearned >= 50 },
      { id: 'kaigo_50pct',   icon: '🏥', title: 'Kaigo Setengah',    xp: 150, check: u => u.kaigoProgress >= 50 },
      { id: 'n5_complete',   icon: '📜', title: 'N5 Selesai',         xp: 300, check: u => u.jlptProgress?.N5 >= 100 },
      { id: 'live_class_1',  icon: '🎥', title: 'Kelas Perdana',      xp: 40,  check: u => u.liveClassCount >= 1 },
      { id: 'live_class_10', icon: '🎓', title: 'Peserta Rajin',      xp: 250, check: u => u.liveClassCount >= 10 },
    ],
    check() {
      const u = State.getUser();
      const already = new Set(u.achievements || []);
      const newly = [];
      this.ALL.forEach(a => {
        if (!already.has(a.id) && a.check(u)) {
          already.add(a.id);
          newly.push(a);
          if (a.xp > 0) State.addXP(a.xp, a.title);
        }
      });
      if (newly.length) {
        State.updateUser({ achievements: [...already] });
        newly.forEach(a => {
          setTimeout(() => Toast.show(`🏅 Achievement: ${a.title}!`, 'success', 4000), 800);
        });
      }
    },
  };

  // ═══════════════════════════════════════════════════════
  // STUDY TIMER
  // ═══════════════════════════════════════════════════════
  const Timer = {
    secs: 0, running: false, iv: null,
    onChange: null,

    start() {
      if (this.running) return;
      this.running = true;
      this.iv = setInterval(() => {
        this.secs++;
        if (this.secs % 60 === 0) {
          State.addStudyMinutes(1);
          State.markStudyToday();
          if (this.secs % 300 === 0) State.addXP(5, '5 menit belajar');
        }
        this.onChange?.(this.secs);
      }, 1000);
    },
    pause() { this.running = false; clearInterval(this.iv); },
    reset() { this.pause(); this.secs = 0; this.onChange?.(0); },
    toggle() { this.running ? this.pause() : this.start(); return this.running; },
    format(s) { return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`; },
  };

  // ═══════════════════════════════════════════════════════
  // INIT
  // ═══════════════════════════════════════════════════════
  document.addEventListener('DOMContentLoaded', () => {
    Theme.init();
    State.markStudyToday();
    Achievements.check();

    // Theme toggle buttons
    document.querySelectorAll('[data-theme-toggle]').forEach(btn => {
      btn.addEventListener('click', () => Theme.toggle());
    });
  });

  // ═══════════════════════════════════════════════════════
  // EXPORTS
  // ═══════════════════════════════════════════════════════
  global.NP = { State, XP, SRS, AI, Toast, Theme, Nav, Timer, Achievements };
  global.NihongoProgress = {
    addXP: (n, r) => State.addXP(n, r),
    logActivity: (type, label, score) => {
      State.markStudyToday();
      if (type === 'quiz') { State.updateUser({ quizTotal: (State.getUser().quizTotal || 0) + 1 }); }
      if (type === 'kanji') { State.updateUser({ kanjiLearned: (State.getUser().kanjiLearned || 0) + 1 }); }
    },
  };

})(window);
